/** Loading of the static data bundle in public/data (generated by the Python pipeline). */
import { loadEphemeris, type Ephemeris } from './ephemeris'
import { loadRaster, type LayerMeta, type RasterField } from './raster'
import type { HorizonMask } from './analysis'

const RASTERS_USED = new Set(['dem_south'])
export const DATA_URL = `${import.meta.env.BASE_URL}data`

export interface Site {
  id: string
  name: string
  lat: number
  lon: number
  group: string // "Artemis III candidate", "Apollo", "CLPS", "Other missions", "Custom"
  note?: string
  heightM?: number
  horizon?: HorizonMask
}

export interface DataBundle {
  sites: Site[]
  layers: LayerMeta[]
  fields: Record<string, RasterField>
  ephemeris: Ephemeris | null
  warnings: string[]
}

async function tryJson<T>(url: string): Promise<T | null> {
  try {
    const r = await fetch(url)
    if (!r.ok) return null
    return (await r.json()) as T
  } catch {
    return null
  }
}

export async function loadBundle(): Promise<DataBundle> {
  const warnings: string[] = []
  const sites = (await tryJson<{ sites: Site[] }>(`${DATA_URL}/sites.json`))?.sites ?? []
  if (!sites.length) warnings.push('sites.json missing: run pipeline/build_sites.py')

  const index = await tryJson<{ layers: LayerMeta[] }>(`${DATA_URL}/overlays/index.json`)
  const layers = index?.layers ?? []
  if (!layers.length) warnings.push('No overlays: run pipeline/overlays.py')

  const fields: Record<string, RasterField> = {}
  // map layers are drawn by the global engine; only the relief basemap still reads a raster (dem_south)
  await Promise.all(
    layers.filter((m) => RASTERS_USED.has(m.id)).map(async (m) => {
      try {
        fields[m.id] = await loadRaster(m, `${DATA_URL}/overlays`)
      } catch (e) {
        warnings.push(`Overlay ${m.id} failed to load: ${e}`)
      }
    }),
  )

  let ephemeris: Ephemeris | null = null
  try {
    ephemeris = await loadEphemeris(`${DATA_URL}/ephemeris.json`)
  } catch {
    warnings.push('ephemeris.json missing: run pipeline/ephemeris.py')
  }
  return { sites, layers, fields, ephemeris, warnings }
}
